#!/usr/bin/env bun
// Regenerates src/docs/embedded-content.ts from every prose doc under
// docs/content/**/*.md so the CLI/search layer can serve docs WITHOUT a docs/
// folder present at runtime — required for a true single-file `bun build --compile`
// binary (a manual disk read would resolve into Bun's temp-extraction dir, which
// never contains sibling files). Run with `bun run embed:docs`; the generated file
// is committed so `bun test` and `bun run build` work without this step first.

import { readdirSync, statSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join, relative } from "node:path";

const HERE = dirname(fileURLToPath(import.meta.url));
const PROJECT_ROOT = join(HERE, "..");
const CONTENT_ROOT = join(PROJECT_ROOT, "docs", "content");
const OUTPUT_PATH = join(PROJECT_ROOT, "src", "docs", "embedded-content.ts");

/** Recursively gather *.md files under root, returning paths relative to the content root. */
function collectMarkdownFiles(root: string): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(root)) {
    const full = join(root, entry);
    if (statSync(full).isDirectory()) out.push(...collectMarkdownFiles(full));
    else if (entry.endsWith(".md")) out.push(relative(CONTENT_ROOT, full));
  }
  return out.sort();
}

/** Serialize one embedded-doc record pair (`relPath -> lines`) as valid TS object syntax. */
function renderEntry(relPath: string, lines: string[]): string {
  // JSON.stringify produces exact string-literal escaping AND is itself valid TS.
  return `${JSON.stringify(relPath)}: ${JSON.stringify(lines)},`;
}

async function main(): Promise<void> {
  const records = await Promise.all(
    collectMarkdownFiles(CONTENT_ROOT).map(async (rel) => [
      rel,
      (await Bun.file(join(CONTENT_ROOT, rel)).text()).split(/\r?\n/),
    ]),
  );

  const body = records.map(([rel, lines]) => renderEntry(rel, lines)).join("\n");

  const banner = "// AUTO-GENERATED by scripts/embed-docs.ts — do not edit by hand.";
  const summary =
    "/**\n" +
    " * Bundled corpus of RoleCall prose docs keyed by path relative to `docs/content`\n" +
    " * (e.g. `concepts/templating.md`). Each value is the source markdown split\n" +
    " * into lines. Regenerated by `scripts/embed-docs.ts`; loadDocuments()\n" +
    " * consumes this map so search works with NO docs/ folder present at runtime,\n" +
    " * which a true single-file `bun build --compile` binary requires.\n" +
    " */";
  const contents = `${banner}\n\n${summary}\nexport const EMBEDDED_DOCS: Record<string, string[]> =\n{\n${body}\n};\n`;

  await Bun.write(OUTPUT_PATH, contents);
  console.log(
    `embed:docs wrote ${records.length} doc(s) -> ${relative(PROJECT_ROOT, OUTPUT_PATH)}`,
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
